import {icon} from './icons.mjs';
import {TODAY,seedTreatments,pending,ordered,future,create,contact,schedule,complete,metrics,nextId} from './continuity.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let rows,warning='';try{rows=JSON.parse(localStorage.getItem('turno-claro-continuity-v1'));if(!Array.isArray(rows)||rows.some(t=>!Array.isArray(t.history)))rows=null;}catch{warning='No se pudieron recuperar los datos locales; se muestra el escenario inicial.';}rows??=seedTreatments();let selected=rows[0]?.id;
const fmt=d=>new Intl.DateTimeFormat('es-EC',{day:'numeric',month:'short',timeZone:'America/Guayaquil'}).format(new Date(d+'T12:00:00-05:00'));
const badge=t=>t.status==='completed'?'Finalizado':future(t)?'Con próxima cita':pending(t)?'Sin próxima cita':'Seguimiento futuro';
function save(){try{localStorage.setItem('turno-claro-continuity-v1',JSON.stringify(rows));return true;}catch{warning='No se pudo guardar. Los cambios sólo duran esta sesión.';return false;}}
function status(s){$('#status').textContent=warning||s;}
function render(){const m=metrics(rows);$('#metrics').innerHTML=`<article><div class="metric-icon coral">${icon("clock")}</div><span>NECESITAN SEGUIMIENTO</span><strong>${m.pending}<small>pacientes pendientes</small></strong><p>Sin próxima cita y con fecha cumplida</p></article><article><div class="metric-icon aqua">${icon("chat")}</div><span>GESTIONES DE HOY</span><strong>${m.contacts}<small>contactos registrados</small></strong><p>Un registro por paciente y día</p></article><article><div class="metric-icon blue">${icon("calendar")}</div><span>CONTACTADOS CON CITA</span><strong>${m.scheduled}<em>/ ${m.contacted}</em><small>pacientes contactados</small></strong><p>Datos del demo · no mide asistencia</p></article>`;
const f=$('#filter').value,q=$('#search').value.toLocaleLowerCase();const visible=ordered(rows).filter(t=>(f==='all'||f==='pending'&&pending(t)||f==='scheduled'&&t.status==='active'&&future(t)||f==='completed'&&t.status==='completed')&&t.name.toLocaleLowerCase().includes(q));
if(!visible.some(t=>t.id===selected))selected=visible[0]?.id;
$('#list').innerHTML=visible.map(t=>{const days=Math.max(0,Math.floor((Date.parse(TODAY)-Date.parse(t.due))/86400000));return `<button class="patient-card ${t.id===selected?'selected':''}" data-id="${esc(t.id)}" aria-pressed="${t.id===selected}"><div class="patient-top"><span class="avatar">${esc(t.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><div><strong>${esc(t.name)}</strong><small>${esc(t.plan)}</small></div><span class="arrow">↗</span></div><div class="progress-row"><span>${t.done} de ${t.total} sesiones registradas</span><span>${Math.round(t.done/t.total*100)} %</span></div><progress value="${t.done}" max="${t.total}" aria-label="Sesiones registradas"></progress><div class="card-bottom"><span class="tag ${pending(t)?'amber':''}">${badge(t)}</span><small>${pending(t)?days?`${days} días desde fecha recomendada`:'Fecha recomendada: hoy':fmt(t.due)}</small></div></button>`;}).join('')||'<div class="empty"><span>✓</span><h3>Todo despejado por aquí</h3><p>No hay pacientes que coincidan con este filtro. Prueba «Todos» o registra un tratamiento.</p></div>';
const t=rows.find(t=>t.id===selected);if(!t){$('#detail').innerHTML='<p class="eyebrow">SIGUIENTE PASO</p><h3>Elige un paciente</h3><p>Aquí verás sus gestiones y podrás registrar una próxima cita.</p>';return;}
const contacted=t.history.some(e=>e.type==='contact'&&e.at.slice(0,10)===TODAY);const allowed=pending(t)&&t.consent&&!contacted;
$('#detail').innerHTML=`<p class="eyebrow">SEGUIMIENTO PERSONAL</p><h2 class="patient-title">${icon("tooth")}${esc(t.name)}</h2><p class="detail-plan">${esc(t.plan)} · ${badge(t)}</p><div class="due"><span>Fecha recomendada</span><strong>${fmt(t.due)}</strong></div>${future(t)?`<p class="scheduled">✓ Próxima cita: ${fmt(t.next.slice(0,10))}, ${esc(t.next.slice(11))}</p>`:''}<div class="message-preview"><span>BORRADOR ADMINISTRATIVO</span><p>Hola, ${esc(t.name.split(' ')[0])}. Desde el consultorio de la Dra. Laura queremos ayudarte a coordinar tu próxima cita. ¿Qué horario te resulta cómodo?</p></div><button id="contact" class="primary full" ${allowed?'':'disabled'}>${contacted?'✓ Contacto registrado hoy':'Registrar contacto simulado'}</button><p class="micro">${!t.consent?'Sin autorización de contacto. No registrar mensajes.':t.status==='completed'?'Tratamiento finalizado.':future(t)?'Ya tiene próxima cita.':contacted?'El paciente sigue pendiente hasta tener próxima cita.':'Registra una gestión; no se envía ningún mensaje.'}</p><form id="schedule-form"><label>Próxima cita acordada<input name="next" type="datetime-local" required min="2026-11-03T09:01" ${t.status==='completed'?'disabled':''}></label><button class="secondary full" ${t.status==='completed'?'disabled':''}>Guardar próxima cita</button><p id="schedule-error" role="alert"></p></form><button id="complete" class="text-button full" ${t.status==='completed'?'disabled':''}>Marcar como finalizado</button><div class="history"><h3>Historial de seguimiento</h3>${t.history.length?[...t.history].reverse().map(e=>`<div class="history-row"><span>●</span><div><strong>${({created:'Registro creado',contact:'Contacto simulado registrado',scheduled:'Próxima cita acordada',completed:'Finalización registrada'})[e.type]}</strong><small>${fmt(e.at.slice(0,10))} · ${e.at.slice(11,16)}${e.next?' → '+esc(e.next.replace('T',' ')):''}</small></div></div>`).join(''):'<p class="micro">Aún no hay gestiones registradas.</p>'}</div>`;
$('#contact').onclick=()=>mutate(()=>contact(t),'Contacto simulado registrado.');$('#complete').onclick=()=>{if(confirm('¿La doctora confirmó la finalización de este tratamiento ficticio?'))mutate(()=>complete(t),'Tratamiento finalizado.');};
$('#schedule-form').onsubmit=e=>{e.preventDefault();try{schedule(t,new FormData(e.target).get('next'));save();render();status('Próxima cita guardada en el demo. Calendar no fue modificado.');}catch(err){$('#schedule-error').textContent=err.message;}};
}
function mutate(fn,msg){try{fn();save();render();status(msg);}catch(err){status(err.message);}}
$('#list').onclick=e=>{const b=e.target.closest('[data-id]');if(b){selected=b.dataset.id;render();}};$('#search').oninput=render;$('#filter').onchange=render;
$('#new-treatment').onclick=()=>{$('#form-error').textContent='';$('#new-dialog').showModal();};$('#close-dialog').onclick=()=>$('#new-dialog').close();
$('#new-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{const t=create(rows,data,nextId(rows));save();$('#filter').value='all';$('#search').value='';selected=t.id;$('#new-dialog').close();e.target.reset();render();status('Tratamiento registrado.');}catch(err){$('#form-error').textContent=err.message;}};
$('#reset').onclick=()=>{if(confirm('¿Restablecer sólo los datos ficticios de continuidad? La agenda se conserva.')){rows=seedTreatments();selected=rows[0].id;warning='';save();$('#filter').value='pending';$('#search').value='';render();status('Continuidad restablecida.');}};render();if(warning)status('');
